// What you will be able to say in an interview:
//
// "Retrieval fires on a partial transcript before the user
//  finishes speaking. About 70% of the time the partial is
//  close enough that the results are still valid, so I keep
//  them. When the final transcript diverges past a threshold
//  I cancel the in-flight generation and re-retrieve."
//
// Very few people applying to the same roles can say this.

interface STT  { stream(audio: AsyncIterable<Buffer>): AsyncIterable<Partial> }
interface LLM  { stream(messages: Msg[], signal: AbortSignal): AsyncIterable<string> }
interface TTS  { speak(text: string, signal: AbortSignal): AsyncIterable<Buffer> }
interface Store{ search(q: string, k: number): Promise<Chunk[]> }

// Every one of them takes an AbortSignal. That is not decoration.
// Phase 5 (barge-in) depends on being able to cancel all of them
// mid-flight, and retrofitting cancellation later is miserable.

// naive: fixed silence timeout
if (silenceMs > 800) endTurn();          // safe, slow, annoying

// better: adaptive
const complete = looksComplete(partialText);   // ends in ?, . or a
                                               // full clause
const threshold = complete ? 300 : 900;
if (silenceMs > threshold) endTurn();

// "where is the auth middleware"   -> complete, cut at 300ms
// "where is the"                   -> incomplete, wait 900ms

// worklet.js
class Capture extends AudioWorkletProcessor {
  process(inputs) {
    const ch = inputs[0][0];
    if (ch) this.port.postMessage(downsample(ch, sampleRate, 16000));
    return true;
  }
}

// main thread
node.port.onmessage = e => ws.send(toInt16(e.data));

// Check: if transcription is consistently poor, log the actual
// sampleRate. It is 48000 far more often than people expect.

let speculative = null;

bus.on("partial", p => {
  if (p.stableFor > 300 && wordCount(p.stableText) >= 4 && !speculative) {
    speculative = {
      query: p.stableText,
      promise: store.search(p.stableText, 10)
    };
  }
});

bus.on("turn-end", async final => {
  const ctx = (speculative && similar(speculative.query, final))
    ? await speculative.promise      // already done, 0ms
    : await store.search(final, 10); // 200ms, guess was wrong
});

function stillValid(spec: string, final: string) {
  if (!final.startsWith(spec)) return false;
  const added = final.slice(spec.length).toLowerCase();
  const flips = ["not", "without", "except", "instead", "but", "rather"];
  return !flips.some(w => added.includes(w));
}

// measured over 50 turns:
//   speculation fired      47
//   kept                   34   (72%)
//   discarded               13
//   wrongly kept             1   <- the honest failure. write about it.

// safe: speculate retrieval, gate the audio
speculativeGen = llm.stream(prompt(specCtx), ac.signal);
buffer = [];
for await (const tok of speculativeGen) buffer.push(tok);   // hold

on("turn-end", final => {
  if (stillValid(spec, final)) flushToTTS(buffer);   // instant
  else { ac.abort(); restart(final); }               // costs nothing visible
});

let buf = "";
for await (const tok of llm.stream(prompt, signal)) {
  buf += tok;
  const s = extractSentence(buf);     // returns null if incomplete
  if (s && s.length > 25) {
    tts.enqueue(s);
    buf = buf.slice(s.length);
  } else if (buf.length > 220) {       // safety flush
    const cut = buf.lastIndexOf(" ", 200);
    tts.enqueue(buf.slice(0, cut));
    buf = buf.slice(cut);
  }
}
if (buf.trim()) tts.enqueue(buf);

class SpeechQueue {
  private q: {i: number, audio: Promise<Buffer>}[] = [];
  private next = 0;

  enqueue(text: string) {
    const i = this.q.length;
    this.q.push({ i, audio: tts.synth(text, this.ac.signal) });
    this.pump();
  }
  async pump() {
    while (this.q[this.next]) {
      await play(await this.q[this.next].audio);   // strict order
      this.next++;
    }
  }
  flush() { this.ac.abort(); this.q = []; this.next = 0; stopPlayback(); }
}

navigator.mediaDevices.getUserMedia({
  audio: {
    echoCancellation: true,
    noiseSuppression: true,
    autoGainControl: true
  }
});

const threshold = isSpeaking ? 200 : 60;   // ms of confirmed speech
if (speechRunMs > threshold) bargeIn();

// Test wearing headphones AND on laptop speakers.
// The speaker case is the one that breaks.

function bargeIn() {
  stopPlayback();          // 1. audio silent immediately
  queue.flush();           // 2. drop pending sentences
  turn.ac.abort();         // 3. synthesis + generation unwind
  spec = null;             // 4. clear speculation
  startTurn();             // 5. new controller, new turn
}

// measure it
console.log("barge-in to silence:", silenceAt - detectedAt, "ms");
// target: under 100ms

// spoken output when a late correction fires:
//
//   "Admin access is enforced by requireRole."   <- speculative
//   "Actually, that was replaced last month by  "  <- correction
//   "the policy middleware in src/policy.ts."
//
// Rule: never cut mid-sentence. Correct at the next boundary.
// Frequency in testing: 3 of 50 turns.
// Users found the correction natural. Mid-sentence cuts they did not.

// event stream to the client
{"type":"sources","items":[
   {"file":"src/middleware/rbac.ts","lines":"12-40","score":8.4},
   {"file":"src/routes/admin.ts","lines":"22-31","score":7.1}]}
{"type":"token","text":"Admin access is enforced by "}
{"type":"token","text":"requireRole."}
{"type":"audio-start","sentence":0}

// Sources render before the first word is spoken.
// The user sees the evidence appear, then hears the answer.

const REFUSAL = "I could not find anything about that in this codebase.";
const refusalAudio = await tts.synth(REFUSAL);   // cached at startup

if (!ctx.length || ctx[0].score < THRESHOLD) {
  ui.emit("sources", []);
  play(refusalAudio);            // instant, no API call
  return;
}

